from docx import Document
import json
import re
import sys
import os

def fill_template(template_path, data_path, output_path):
    print(f"Loading data from {data_path}...")
    with open(data_path, 'r') as f:
        data = json.load(f)

    # Handle Conditional Logic for RELOCATION
    if data.get("RELOCATION_PACKAGE") == "Yes":
        print("Relocation package is YES. Removing markers, keeping content.")
        data["IF_RELOCATION"] = ""
        data["END_IF_RELOCATION"] = ""
    else:
        print("Warning: RELOCATION_PACKAGE is not Yes. Logic for 'No' is not implemented as per current requirements (assuming Yes).")

    print(f"Loading template from {template_path}...")
    doc = Document(template_path)

    def replace_in_para(para):
        text = para.text
        # Regex to find {{KEY}}
        pattern = r'\{\{([A-Z_]+)\}\}'

        # Check if any placeholder exists
        if not re.search(pattern, text):
            return

        new_text = text
        matches = re.findall(pattern, text)
        if not matches:
            return

        replacement_made = False
        for key in matches:
            placeholder = '{{' + key + '}}'
            if key in data:
                val = str(data[key])
                new_text = new_text.replace(placeholder, val)
                replacement_made = True
            else:
                # Key not found in data
                pass

        if replacement_made and new_text != text:
            # Apply replacement by setting the text of the first run and clearing others.
            # This preserves the paragraph-level style but unifies the run-level style to the first run.
            if para.runs:
                para.runs[0].text = new_text
                for run in para.runs[1:]:
                    run.text = ''

    # 1. Main paragraphs
    for para in doc.paragraphs:
        replace_in_para(para)

    # 2. Tables
    def process_table(table):
        for row in table.rows:
            for cell in row.cells:
                for para in cell.paragraphs:
                    replace_in_para(para)
                for nested in cell.tables:
                    process_table(nested)

    for table in doc.tables:
        process_table(table)

    # 3. Sections (Headers/Footers)
    for section in doc.sections:
        # Header
        for para in section.header.paragraphs:
            replace_in_para(para)
        # Footer
        for para in section.footer.paragraphs:
            replace_in_para(para)

    print(f"Saving to {output_path}...")
    doc.save(output_path)
    print("Done.")

if __name__ == "__main__":
    fill_template('/root/offer_letter_template.docx', '/root/employee_data.json', '/root/offer_letter_filled.docx')

